  }, pairedItem: { item: inputIndex } };
}
return (async () => {
  const outputs = [];
  for (const item of $input.all()) {
    const raw = item.json || {};
    const receipt = raw.__legacyReceipt && typeof raw.__legacyReceipt === 'object' ? raw.__legacyReceipt : {};
    const inputIndex = Number(raw.__legacyInputIndex);
    const isWrite = raw.__legacyWrite === true || WRITE_OPERATIONS.has(String(receipt.operation || ''));
    try {
      if (!Number.isInteger(inputIndex) || inputIndex < 0) throw Object.assign(new Error('legacy receipt inputIndex 无效'), { code: 'LEGACY_RECEIPT_INVALID', beforeSend: true });
      const receiptKeys = new Set(['requestRef','operation','payloadHash','statusCode','result','deliveryState','retryClass','retryAfterMs']);
      if (Object.keys(receipt).some((key) => !receiptKeys.has(key))
        || !String(receipt.requestRef || '')
        || !String(receipt.operation || '')
        || !/^sha256:[a-f0-9]{64}$/.test(String(receipt.payloadHash || ''))
        || !Number.isInteger(Number(receipt.statusCode))
        || !receipt.result || typeof receipt.result !== 'object' || Array.isArray(receipt.result)
        || !['NOT_SENT','UNKNOWN','RESPONDED'].includes(String(receipt.deliveryState || ''))
        || !['NONE','READBACK_REQUIRED','RETRYABLE','PERMANENT'].includes(String(receipt.retryClass || ''))) {
        throw Object.assign(new Error('legacy receipt 请求合同无效'), { code: 'LEGACY_RECEIPT_INVALID', beforeSend: true });
      }
      const data = await ozonRuntimeRequest('POST', '/api/v1/ozon/runtime/gateway/legacy-receipt', receipt, 60000);
      const deliveryState = String(data.deliveryState || '');
      const retryClass = String(data.retryClass || '');
      if (!['NOT_SENT','UNKNOWN','RESPONDED'].includes(deliveryState)
        || !['NONE','READBACK_REQUIRED','RETRYABLE','PERMANENT'].includes(retryClass)
        || String(data.requestRef || '') !== String(receipt.requestRef || '')
        || String(data.operation || '') !== String(receipt.operation || '')
        || (data.result && typeof data.result === 'object' && Object.prototype.hasOwnProperty.call(data.result, '__merchRouteLegacy'))) {
        throw Object.assign(new Error('历史凭据回执响应合同无效'), { code: 'LEGACY_RECEIPT_RESPONSE_INVALID' });
      }
      const result = data.result && typeof data.result === 'object' ? data.result : {};
      outputs.push({ json: { ...data, result, body: result, requestId: String(receipt.requestRef), inputIndex }, pairedItem: { item: inputIndex } });
    } catch (error) {
      outputs.push(receiptFailure(error, receipt, Number.isInteger(inputIndex) ? inputIndex : 0, isWrite));
    }
  }
  return outputs;
})();

function sanitize(value, depth = 0) {
  if (depth > 12) return '[TRUNCATED]';
  if (Array.isArray(value)) return value.map((entry) => sanitize(entry, depth + 1));
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value)
    .filter(([key]) => !String(key).startsWith('__merchRoute') && !String(key).startsWith('__legacy'))
    .map(([key, entry]) => [key, /authorization|client[-_]?id|api[-_]?key|cookie|secret|credential/i.test(key) ? '[REDACTED]' : sanitize(entry, depth + 1)]));
}
return $input.all().map((item, index) => ({ json: sanitize(item.json || {}), pairedItem: item.pairedItem ?? { item: index } }));

